//! Acceptance tests for VIZ.VIEW.STATE (`fid_view::state`).
//!
//! Expected bytes and digests come from `fixtures/viz/viewstate-samples/make_fixtures.py`, an
//! independent stdlib-Python RFC 8785 writer; the error labels in `invalid/expected.txt` are hand
//! labels from NODE.md Design. Nothing here is generated by running this crate.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_types::Digest;
use fid_view::state::{
    parse, parse_canonical, Camera, ClipPlane, EntityId, LegendLayoutRef, Projection, References, TransparencyEntry,
    ViewState, ViewStateError, Viewport, VisibilityRule, MAX_CLIP_PLANES, MAX_ENTRIES, MAX_INPUT_BYTES, SCHEMA_VERSION,
};
use std::path::PathBuf;

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/viz/viewstate-samples")
}

fn read(rel: &str) -> Vec<u8> {
    let p = dir().join(rel);
    std::fs::read(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()))
}

fn text(rel: &str) -> String {
    String::from_utf8(read(rel)).unwrap()
}

/// (file, digest) rows of digests.txt.
fn golden() -> Vec<(String, String)> {
    text("digests.txt")
        .lines()
        .map(|l| {
            let (f, d) = l.split_once(' ').unwrap();
            (f.to_string(), d.to_string())
        })
        .collect()
}

// ------------------------------------------------------------------ AC-1, AC-5

#[test]
fn ac1_samples_round_trip_byte_identical() {
    let rows = golden();
    assert_eq!(rows.len(), 20, "AC-1 names 20 hand-written ViewStates");
    for (file, _) in &rows {
        let input = read(&format!("samples/{file}"));
        let vs = parse_canonical(&input).unwrap_or_else(|e| panic!("{file}: {e}"));
        let out = vs.to_canonical_bytes().unwrap();
        assert_eq!(out, input, "{file}: parse then serialise changed the bytes");
        // parse, serialise, parse is a fixed point too.
        let again = parse(&out).unwrap();
        assert_eq!(again, vs, "{file}");
        assert_eq!(again.to_canonical_bytes().unwrap(), input, "{file}");
    }
}

#[test]
fn ac5_schema_1_digests_match_the_golden_digests() {
    for (file, want) in golden() {
        let vs = parse_canonical(&read(&format!("samples/{file}"))).unwrap();
        assert_eq!(vs.schema, 1);
        assert_eq!(vs.digest().unwrap().as_str(), want, "{file}");
    }
}

#[test]
fn seed3_reference_cases_match_bytes_and_digests() {
    let body = text("generated.txt");
    let mut n = 0;
    for line in body.lines() {
        let (want, json) = line.split_once(' ').unwrap();
        let vs = parse_canonical(json.as_bytes()).unwrap_or_else(|e| panic!("line {n}: {e}"));
        assert_eq!(vs.to_canonical_bytes().unwrap(), json.as_bytes(), "line {n}");
        assert_eq!(vs.digest().unwrap().as_str(), want, "line {n}");
        n += 1;
    }
    assert_eq!(n, 200);
}

#[test]
fn lenient_inputs_parse_to_the_reference_canonical_form() {
    let names = ["pretty", "crlf", "number-spellings", "negative-zero", "upper-case-uuid"];
    for name in names {
        let input = read(&format!("lenient/{name}.json"));
        let want = read(&format!("lenient/{name}.canonical.json"));
        let vs = parse(&input).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(vs.to_canonical_bytes().unwrap(), want, "{name}");
        match parse_canonical(&input) {
            Err(ViewStateError::NotCanonical { .. }) => {}
            other => panic!("{name}: expected NotCanonical, got {other:?}"),
        }
        assert!(parse_canonical(&want).is_ok(), "{name}");
    }
}

// ------------------------------------------------------------------ AC-4 and the error table

#[test]
fn ac4_nan_camera_coordinate_and_65_clip_planes() {
    let e = parse(&read("invalid/nan-eye.json")).unwrap_err();
    assert_eq!(e, ViewStateError::NonFiniteNumber { field: "camera.eye_m[1]".to_string() });
    let e = parse(&read("invalid/clips-65.json")).unwrap_err();
    assert_eq!(e, ViewStateError::LimitExceeded { field: "clips".to_string(), limit: MAX_CLIP_PLANES });

    // The same two faults in an in-memory ViewState fail serialisation with the same types.
    let mut vs = sample_state();
    vs.camera.eye_m[2] = f64::NAN;
    assert_eq!(vs.to_canonical_bytes(), Err(ViewStateError::NonFiniteNumber { field: "camera.eye_m[2]".to_string() }));
    let mut vs = sample_state();
    vs.clips = (0..65).map(|i| ClipPlane { id: i, normal: [0.0, 0.0, 1.0], offset_m: 0.0 }).collect();
    assert_eq!(vs.digest(), Err(ViewStateError::LimitExceeded { field: "clips".to_string(), limit: MAX_CLIP_PLANES }));
}

#[test]
fn invalid_fixtures_fail_with_the_hand_labelled_error_and_field() {
    let labels = text("invalid/expected.txt");
    let mut n = 0;
    for line in labels.lines() {
        let mut parts = line.split(' ');
        let (file, code, field) = (parts.next().unwrap(), parts.next().unwrap(), parts.next().unwrap());
        let e = parse(&read(&format!("invalid/{file}"))).expect_err(file);
        assert_eq!((e.code(), e.field()), (code, field), "{file}: {e}");
        assert!(parse_canonical(&read(&format!("invalid/{file}"))).is_err(), "{file}");
        n += 1;
    }
    assert!(n >= 40, "{n}");
}

#[test]
fn input_size_and_entry_limits_fail_closed() {
    let big = vec![b' '; MAX_INPUT_BYTES + 1];
    assert_eq!(parse(&big), Err(ViewStateError::LimitExceeded { field: "$".to_string(), limit: MAX_INPUT_BYTES }));

    // 100 001 visibility entries: refused before any entry is decoded or validated.
    let mut empty = sample_state();
    empty.visibility.clear();
    empty.transparency.clear();
    let base = String::from_utf8(empty.to_canonical_bytes().unwrap()).unwrap();
    assert!(base.contains(r#""visibility":[]"#) && base.contains(r#""transparency":[]"#));
    let entry = r#"{"entity":"00000000-0000-0000-0000-000000000000","visible":true}"#;
    let many = vec![entry; MAX_ENTRIES + 1].join(",");
    let json = base.replace(r#""visibility":[]"#, &format!(r#""visibility":[{many}]"#));
    assert_eq!(
        parse(json.as_bytes()),
        Err(ViewStateError::LimitExceeded { field: "visibility".to_string(), limit: MAX_ENTRIES })
    );

    // Exactly at the limit is accepted (distinct entities).
    let at_limit: Vec<String> =
        (0..MAX_ENTRIES).map(|i| format!(r#"{{"alpha":1,"entity":"{}"}}"#, EntityId::from_u128(i as u128))).collect();
    let json = base.replace(r#""transparency":[]"#, &format!(r#""transparency":[{}]"#, at_limit.join(",")));
    let vs = parse_canonical(json.as_bytes()).unwrap();
    assert_eq!(vs.transparency.len(), MAX_ENTRIES);

    // Bare commas inside an array are counted before any tree is built.
    let commas = format!("[{}]", "0,".repeat(500_000) + "0");
    assert_eq!(parse(commas.as_bytes()).unwrap_err().code(), "limit_exceeded");

    let mut vs = sample_state();
    vs.transparency =
        (0..=MAX_ENTRIES as u128).map(|i| TransparencyEntry { entity: EntityId::from_u128(i), alpha: 0.5 }).collect();
    assert_eq!(
        vs.validate(),
        Err(ViewStateError::LimitExceeded { field: "transparency".to_string(), limit: MAX_ENTRIES })
    );
}

#[test]
fn unsupported_schema_is_reported_on_write_too() {
    let mut vs = sample_state();
    vs.schema = 2;
    assert_eq!(vs.to_canonical_bytes(), Err(ViewStateError::UnsupportedSchema { found: 2 }));
    assert_eq!(SCHEMA_VERSION, 1);
}

/// A change to a valid ViewState.
type Mutation = Box<dyn Fn(&mut ViewState)>;

#[test]
fn in_memory_validation_names_the_field() {
    let cases: Vec<(Mutation, &str, &str)> = vec![
        (Box::new(|v| v.camera.up = [0.0, 0.0, 0.0]), "degenerate_camera", "camera.up"),
        (Box::new(|v| v.camera.target_m = v.camera.eye_m), "degenerate_camera", "camera.target_m"),
        (Box::new(|v| v.camera.near_m = v.camera.far_m), "degenerate_camera", "camera.far_m"),
        (
            Box::new(|v| v.camera.projection = Projection::Perspective { fov_y_rad: 4.0 }),
            "degenerate_camera",
            "camera.projection.fov_y_rad",
        ),
        (
            Box::new(|v| v.camera.projection = Projection::Ortho { height_m: f64::INFINITY }),
            "non_finite_number",
            "camera.projection.height_m",
        ),
        (
            Box::new(|v| {
                v.camera.eye_m = [-1e308, 0.0, 0.0];
                v.camera.target_m = [1e308, 0.0, 0.0];
            }),
            "degenerate_camera",
            "camera.target_m",
        ),
        (Box::new(|v| v.clips[1].normal = [0.0, 0.0, 0.0]), "degenerate_normal", "clips[1].normal"),
        (Box::new(|v| v.clips[0].normal = [0.0, 0.0, 2.0]), "non_unit_normal", "clips[0].normal"),
        (Box::new(|v| v.clips[0].normal = [1e200, 0.0, 0.0]), "non_unit_normal", "clips[0].normal"),
        (Box::new(|v| v.clips[1].offset_m = f64::NEG_INFINITY), "non_finite_number", "clips[1].offset_m"),
        (Box::new(|v| v.clips[1].id = v.clips[0].id), "duplicate_key", "clips[1].id"),
        (Box::new(|v| v.transparency[0].alpha = f64::NAN), "non_finite_number", "transparency[0].alpha"),
        (Box::new(|v| v.transparency[0].alpha = 1.0 + f64::EPSILON), "out_of_range", "transparency[0].alpha"),
        (Box::new(|v| v.viewport.width_px = 0), "out_of_range", "viewport.width_px"),
    ];
    for (i, (f, code, field)) in cases.iter().enumerate() {
        let mut vs = sample_state();
        f(&mut vs);
        let e = vs.validate().unwrap_err();
        assert_eq!((e.code(), e.field()), (*code, *field), "case {i}: {e}");
        assert_eq!(vs.to_canonical_bytes().unwrap_err(), e, "case {i}");
    }
}

struct Doc {
    entities: Vec<EntityId>,
    colormap: Option<Digest>,
}

impl References for Doc {
    fn has_entity(&self, id: &EntityId) -> bool {
        self.entities.contains(id)
    }
    fn has_colormap(&self, d: &Digest) -> bool {
        self.colormap.as_ref() == Some(d)
    }
    fn has_legend_layout(&self, _: &LegendLayoutRef) -> bool {
        true
    }
    fn has_label_set(&self, _: &EntityId) -> bool {
        false
    }
}

#[test]
fn unknown_references_fail_closed_and_are_all_listed() {
    let vs = sample_state();
    let full = Doc {
        entities: vs.visibility.iter().map(|v| v.entity).chain(vs.transparency.iter().map(|t| t.entity)).collect(),
        colormap: vs.colormap,
    };
    let mut ok = vs.clone();
    ok.labels = None;
    assert_eq!(ok.check_references(&full), Ok(()));
    assert_eq!(vs.check_references(&full), Err(ViewStateError::UnknownReference { field: "labels".to_string() }));

    let empty = Doc { entities: vec![], colormap: None };
    assert_eq!(
        vs.unknown_references(&empty),
        vec!["colormap", "labels", "visibility[0].entity", "visibility[1].entity", "transparency[0].entity"]
    );
    assert_eq!(vs.check_references(&empty).unwrap_err().field(), "colormap");
}

// ------------------------------------------------------------------ AC-3

#[test]
fn ac3_insertion_order_does_not_change_bytes_or_digest() {
    let a = sample_state();
    let mut b = a.clone();
    b.clips.reverse();
    b.visibility.reverse();
    b.transparency.rotate_left(1);
    assert_ne!(a, b);
    assert_eq!(a.to_canonical_bytes().unwrap(), b.to_canonical_bytes().unwrap());
    assert_eq!(a.digest().unwrap(), b.digest().unwrap());

    // Every permutation of four clip planes gives one byte string.
    let planes: Vec<ClipPlane> = [7u32, 3, 11, 0]
        .iter()
        .map(|&id| ClipPlane { id, normal: [0.0, 1.0, 0.0], offset_m: f64::from(id) * 0.5 })
        .collect();
    let mut seen = None;
    for p in permutations(&planes) {
        let mut v = a.clone();
        v.clips = p;
        let bytes = v.to_canonical_bytes().unwrap();
        match &seen {
            None => seen = Some(bytes),
            Some(s) => assert_eq!(&bytes, s),
        }
    }

    let mut sorted = b.clone();
    sorted.sort_collections();
    let mut a_sorted = a.clone();
    a_sorted.sort_collections();
    assert_eq!(sorted, a_sorted);
}

fn permutations<T: Clone>(items: &[T]) -> Vec<Vec<T>> {
    if items.len() <= 1 {
        return vec![items.to_vec()];
    }
    let mut out = Vec::new();
    for i in 0..items.len() {
        let mut rest = items.to_vec();
        let head = rest.remove(i);
        for mut p in permutations(&rest) {
            p.insert(0, head.clone());
            out.push(p);
        }
    }
    out
}

// ------------------------------------------------------------------ AC-2 (property, seed 3)

/// SplitMix64, written here independently of the Python generator.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }

    /// Any finite f64: random bit patterns (all exponents), subnormals, +0 and -0.
    fn any_f64(&mut self) -> f64 {
        match self.below(6) {
            0 => 0.0,
            1 => -0.0,
            2 => f64::from_bits((self.next() & 0x800F_FFFF_FFFF_FFFF) | 1),
            _ => loop {
                let v = f64::from_bits(self.next());
                if v.is_finite() {
                    break v;
                }
            },
        }
    }

    /// A finite f64 with |exponent| <= 60, a subnormal, or a zero (differences stay finite).
    fn coord(&mut self) -> f64 {
        match self.below(5) {
            0 => 0.0,
            1 => -0.0,
            2 => f64::from_bits((self.next() & 0x800F_FFFF_FFFF_FFFF) | 1),
            _ => {
                let sign = self.next() & (1 << 63);
                let exp = 1023 - 60 + self.below(121);
                f64::from_bits(sign | (exp << 52) | (self.next() & 0x000F_FFFF_FFFF_FFFF))
            }
        }
    }

    fn unit01(&mut self) -> f64 {
        match self.below(5) {
            0 => -0.0,
            1 => 1.0,
            2 => f64::from_bits((self.next() & 0x000F_FFFF_FFFF_FFFF) | 1),
            _ => (self.next() >> 11) as f64 / (1u64 << 53) as f64,
        }
    }
}

fn gen_state(r: &mut Rng) -> ViewState {
    let v3 = |r: &mut Rng| [r.coord(), r.coord(), r.coord()];
    let eye_m = v3(r);
    let target_m = v3(r);
    let up = v3(r);
    let (projection, near_m, far_m) = if r.below(2) == 0 {
        let fov = 1e-6 + (r.next() >> 11) as f64 / (1u64 << 53) as f64 * 3.0;
        let near = r.coord().abs();
        let near = if near == 0.0 { 1e-3 } else { near };
        (Projection::Perspective { fov_y_rad: fov }, near, near * 4.0 + 1e-3)
    } else {
        let near = r.coord();
        (Projection::Ortho { height_m: r.coord().abs() + f64::MIN_POSITIVE }, near, near.abs() + 1.0)
    };
    let mut clips = Vec::new();
    for _ in 0..r.below(8) {
        let raw = [r.coord(), r.coord(), r.coord()];
        let m = raw.iter().fold(0.0f64, |m, c| if c.abs() > m { c.abs() } else { m });
        if m == 0.0 {
            continue;
        }
        let s = [raw[0] / m, raw[1] / m, raw[2] / m];
        let len = (s[0] * s[0] + s[1] * s[1] + s[2] * s[2]).sqrt();
        clips.push(ClipPlane {
            id: r.next() as u32,
            normal: [s[0] / len, s[1] / len, s[2] / len],
            offset_m: r.any_f64(),
        });
    }
    let visibility = (0..r.below(6))
        .map(|_| VisibilityRule {
            entity: EntityId::from_u128(u128::from(r.next()) << 64 | u128::from(r.next())),
            visible: r.below(2) == 0,
        })
        .collect();
    let transparency = (0..r.below(6))
        .map(|_| TransparencyEntry {
            entity: EntityId::from_u128(u128::from(r.next()) << 64 | u128::from(r.next())),
            alpha: r.unit01(),
        })
        .collect();
    let mut digest_bytes = [0u8; 32];
    for b in digest_bytes.iter_mut() {
        *b = r.next() as u8;
    }
    ViewState {
        schema: 1,
        camera: Camera { eye_m, target_m, up, projection, near_m, far_m },
        viewport: Viewport { width_px: 1 + r.below(32_768) as u32, height_px: 1 + r.below(32_768) as u32 },
        clips,
        visibility,
        transparency,
        colormap: if r.below(2) == 0 { Some(Digest::from_bytes(digest_bytes)) } else { None },
        legend: if r.below(2) == 0 { Some(LegendLayoutRef(Digest::from_bytes([7; 32]))) } else { None },
        labels: if r.below(2) == 0 { Some(EntityId::from_u128(u128::from(r.next()))) } else { None },
    }
}

/// The bits a value must parse back to: its own, except -0.0, which is written `0` (NODE.md).
fn expected_bits(v: f64) -> u64 {
    if v == 0.0 {
        0
    } else {
        v.to_bits()
    }
}

fn floats(vs: &ViewState) -> Vec<f64> {
    let c = &vs.camera;
    let mut out: Vec<f64> = c.eye_m.iter().chain(&c.target_m).chain(&c.up).copied().collect();
    out.push(match c.projection {
        Projection::Perspective { fov_y_rad } => fov_y_rad,
        Projection::Ortho { height_m } => height_m,
    });
    out.push(c.near_m);
    out.push(c.far_m);
    for p in &vs.clips {
        out.extend_from_slice(&p.normal);
        out.push(p.offset_m);
    }
    out.extend(vs.transparency.iter().map(|t| t.alpha));
    out
}

#[test]
fn ac2_seed3_f64_bit_patterns_survive_the_round_trip() {
    let mut r = Rng(3);
    let (mut checked, mut drawn, mut zeros, mut neg_zeros, mut subnormals) = (0, 0, 0, 0, 0);
    while checked < 10_000 {
        drawn += 1;
        assert!(drawn < 20_000, "generator yields too few valid states");
        let mut vs = gen_state(&mut r);
        if vs.validate().is_err() {
            continue;
        }
        vs.sort_collections();
        let bytes = vs.to_canonical_bytes().unwrap();
        let back = parse_canonical(&bytes).unwrap();
        let (a, b) = (floats(&vs), floats(&back));
        assert_eq!(a.len(), b.len());
        for (x, y) in a.iter().zip(&b) {
            assert_eq!(y.to_bits(), expected_bits(*x), "{x:e} came back as {y:e}");
            zeros += usize::from(*x == 0.0);
            neg_zeros += usize::from(x.to_bits() == 1 << 63);
            subnormals += usize::from(x.is_subnormal());
        }
        assert_eq!(back.to_canonical_bytes().unwrap(), bytes);
        checked += 1;
    }
    assert!(zeros > 1_000 && neg_zeros > 1_000 && subnormals > 1_000, "{zeros} {neg_zeros} {subnormals}");
}

#[test]
fn negative_zero_serialises_as_zero_with_the_same_digest() {
    let a = sample_state();
    let mut b = a.clone();
    b.camera.eye_m[0] = -0.0;
    let mut c = a.clone();
    c.camera.eye_m[0] = 0.0;
    assert_eq!(b.to_canonical_bytes().unwrap(), c.to_canonical_bytes().unwrap());
    assert_eq!(b.digest().unwrap(), c.digest().unwrap());
    let back = parse(&b.to_canonical_bytes().unwrap()).unwrap();
    assert_eq!(back.camera.eye_m[0].to_bits(), 0);
}

// ------------------------------------------------------------------ no panics on hostile input

#[test]
fn truncated_and_corrupted_inputs_never_panic() {
    let mut r = Rng(3);
    for (file, _) in golden().into_iter().filter(|(f, _)| !f.starts_with("19-")) {
        let input = read(&format!("samples/{file}"));
        for cut in 0..input.len() {
            assert!(parse(&input[..cut]).is_err(), "{file} cut at {cut}");
        }
        for _ in 0..200 {
            let mut m = input.clone();
            for _ in 0..1 + r.below(3) {
                let i = r.below(m.len() as u64) as usize;
                m[i] = r.next() as u8;
            }
            let _ = parse(&m);
            let _ = parse_canonical(&m);
        }
    }
}

#[test]
fn error_codes_are_stable() {
    let all = [
        (ViewStateError::Malformed { field: "a".into(), reason: "r".into() }, "malformed"),
        (ViewStateError::NonFiniteNumber { field: "a".into() }, "non_finite_number"),
        (ViewStateError::LimitExceeded { field: "a".into(), limit: 1 }, "limit_exceeded"),
        (ViewStateError::UnsupportedSchema { found: 9 }, "unsupported_schema"),
        (ViewStateError::DegenerateCamera { field: "a".into(), reason: "r" }, "degenerate_camera"),
        (ViewStateError::DegenerateNormal { field: "a".into() }, "degenerate_normal"),
        (ViewStateError::NonUnitNormal { field: "a".into() }, "non_unit_normal"),
        (ViewStateError::OutOfRange { field: "a".into(), reason: "r" }, "out_of_range"),
        (ViewStateError::DuplicateKey { field: "a".into() }, "duplicate_key"),
        (ViewStateError::UnknownReference { field: "a".into() }, "unknown_reference"),
        (ViewStateError::NotCanonical { at: 3 }, "not_canonical"),
    ];
    for (e, code) in all {
        assert_eq!(e.code(), code);
        assert!(e.to_string().starts_with(code), "{e}");
    }
}

/// A valid state with two clips, two visibility rules, one transparency entry and references.
fn sample_state() -> ViewState {
    ViewState {
        schema: 1,
        camera: Camera {
            eye_m: [0.3, -0.2, 0.5],
            target_m: [0.0, 0.0, 0.0],
            up: [0.0, 0.0, 1.0],
            projection: Projection::Perspective { fov_y_rad: 0.6 },
            near_m: 0.01,
            far_m: 10.0,
        },
        viewport: Viewport { width_px: 1280, height_px: 720 },
        clips: vec![
            ClipPlane { id: 9, normal: [0.0, 0.0, 1.0], offset_m: 0.1 },
            ClipPlane { id: 2, normal: [0.6, 0.8, 0.0], offset_m: -0.05 },
        ],
        visibility: vec![
            VisibilityRule { entity: EntityId::from_u128(0x2222), visible: false },
            VisibilityRule { entity: EntityId::from_u128(0x1111), visible: true },
        ],
        transparency: vec![TransparencyEntry { entity: EntityId::from_u128(0x3333), alpha: 0.35 }],
        colormap: Some(Digest::from_bytes([0xab; 32])),
        legend: Some(LegendLayoutRef(Digest::from_bytes([0xcd; 32]))),
        labels: Some(EntityId::from_u128(0x4444)),
    }
}
